const item = $input.first().json;

// 1. Extract Gemini's response text
const raw = item.content?.parts?.[0]?.text;

if (!raw) {
  throw new Error(
    'Gemini response text not found. Check the Message a model output.'
  );
}

// 2. Remove Markdown code fences if present
const cleaned = raw
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

// 3. Parse the JSON response
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    'Gemini returned invalid JSON: ' + error.message
  );
}

// 4. Check that exactly five questions exist
if (
  !Array.isArray(parsed.questions) ||
  parsed.questions.length !== 5
) {
  throw new Error(
    'Expected exactly 5 questions. Received: ' +
    (parsed.questions?.length ?? 0)
  );
}

// 5. Validate and repair each question
for (let i = 0; i < parsed.questions.length; i++) {
  const q = parsed.questions[i];

  if (!q || typeof q !== 'object') {
    throw new Error(`Question ${i + 1} is not an object.`);
  }

  // Ensure options is an object
  if (!q.options || typeof q.options !== 'object') {
    throw new Error(
      `Question ${i + 1} has missing or invalid options.`
    );
  }

  const options = q.options;

  // Repair malformed option keys.
  // Preserve A, B, and C; use an unexpected key for D
  // when D is missing.
  if (!options.D) {
    const malformedKey = Object.keys(options).find(
      key => !['A', 'B', 'C'].includes(key)
    );

    if (malformedKey) {
      options.D = options[malformedKey];
      delete options[malformedKey];
    }
  }

  // Clean option text
  for (const key of ['A', 'B', 'C', 'D']) {
    if (options[key] !== undefined) {
      options[key] = String(options[key]).trim();
    }
  }

  // Normalize the correct answer
  let answer = String(q.correct_answer ?? '')
    .replace(/["'`]/g, '')
    .trim()
    .toUpperCase();

  // Accept values like "B." or "Answer: B"
  const answerMatch = answer.match(/\b([A-D])\b/);
  q.correct_answer = answerMatch ? answerMatch[1] : '';

  // Validate the question
  if (
    !q.question ||
    !options.A ||
    !options.B ||
    !options.C ||
    !options.D ||
    !['A', 'B', 'C', 'D'].includes(q.correct_answer)
  ) {
    throw new Error(
      `Invalid question ${i + 1}: ` +
      JSON.stringify(q)
    );
  }

  q.question = String(q.question).trim();
  q.explanation = String(q.explanation ?? '').trim();
}

// 6. Prepare quiz state for Google Sheets
const chatId = String(
  $('Telegram Trigger').first().json.message.chat.id
);

return [
  {
    json: {
      chat_id: chatId,
      questions_json: JSON.stringify(parsed.questions),
      current_question: 0,
      score: 0,
      total_questions: 5,
      status: 'active',
      last_answer: ''
    }
  }
];

const state = $('Parse Quiz JSON').first().json;
const questions = JSON.parse(state.questions_json);
const q = questions[0];

return [{
  json: {
    chat_id: state.chat_id,
    reply_text:
      `🧠 StudyMate Quiz — Question 1/5\n\n` +
      `${q.question}\n\n` +
      `A) ${q.options.A}\n` +
      `B) ${q.options.B}\n` +
      `C) ${q.options.C}\n` +
      `D) ${q.options.D}\n\n` +
      `Reply with A, B, C, or D.`
  }
}];

const state = $input.first().json;

if (state.status !== 'active') {
  throw new Error('No active quiz found.');
}

const questions = JSON.parse(state.questions_json);
const index = Number(state.current_question);
const previousScore = Number(state.score);
const total = Number(state.total_questions);

const answer = String(
  $('Telegram Trigger').first().json.message.text
).trim().toUpperCase();

if (!['A', 'B', 'C', 'D'].includes(answer)) {
  throw new Error('Please answer using A, B, C, or D.');
}

const question = questions[index];

if (!question) {
  throw new Error('The current quiz question could not be found.');
}

const correct = answer === question.correct_answer;
const score = previousScore + (correct ? 1 : 0);
const nextIndex = index + 1;
const finished = nextIndex >= total;

let reply =
  `${correct ? '✅ Correct!' : '❌ Incorrect.'}\n` +
  `Correct answer: ${question.correct_answer}\n` +
  `${question.explanation}\n\n`;

if (finished) {
  reply +=
    `🏆 Quiz completed!\n` +
    `Final score: ${score}/${total}\n` +
    `Percentage: ${Math.round((score / total) * 100)}%\n\n` +
    `Send /quiz to try again.`;
} else {
  const next = questions[nextIndex];

  reply +=
    `🧠 Question ${nextIndex + 1}/${total}\n\n` +
    `${next.question}\n\n` +
    `A) ${next.options.A}\n` +
    `B) ${next.options.B}\n` +
    `C) ${next.options.C}\n` +
    `D) ${next.options.D}\n\n` +
    `Reply with A, B, C, or D.`;
}

return [{
  json: {
    chat_id: String(state.chat_id),
    questions_json: state.questions_json,
    current_question: nextIndex,
    score,
    total_questions: total,
    status: finished ? 'completed' : 'active',
    last_answer: answer,
    reply_text: reply
  }
}];

const rows = $input.all().map(item => item.json);

if (rows.length === 0) {
  return [{ json: { pdf_text: '', document_name: '' } }];
}

rows.sort((a, b) => {
  return new Date(b.uploaded_at).getTime()
       - new Date(a.uploaded_at).getTime();
});

return [{ json: rows[0] }];
